#include <iostream>
class Point {
public:
    double x, y;
    double distance() const { return std::sqrt(x * x + y * y); }
};

int main() {
    Point obj{3.0, 4.0};
    double (Point::*pmf)() const = &Point::distance;
    double result = (obj.*pmf)();
    std::cout << "Distance: " << result << std::endl;
    return 0;
}
